 "content": "def transform(grid):
    """Move the non-background object up to a full-width stripe and leave an 8 trail."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # Locate a complete horizontal or vertical barrier, if present.
    barrier = None
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != bg:
            barrier = ('h', r, row[0])
            break
    if barrier is None:
        for c in range(w):
            vals = [grid[r][c] for r in range(h)]
            if len(set(vals)) == 1 and vals[0] != bg:
                barrier = ('v', c, vals[0])
                break
    if barrier is None:
        return [row[:] for row in grid]
    axis, pos, barrier_color = barrier

    # Object color is the non-background, non-barrier color(s); keep its exact shape.
    object_colors = {v for row in grid for v in row if v not in (bg, barrier_color)}
    if not object_colors:
        return [row[:] for row in grid]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] in object_colors]
    if not points:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)

    out = [row[:] for row in grid]
    # Remove the object from its original location, then place it nearest the barrier.
    for r, c in points:
        out[r][c] = bg
    if axis == 'h':
        above = r1 < pos
        height = r1 - r0 + 1
        nr0 = pos - height if above else pos + 1
        dr = nr0 - r0
        for r, c in points:
            out[r + dr][c] = grid[r][c]
        # The wake is the next full row on the object's far side.
        wake = nr0 - 1 if above else nr0 + height
        if 0 <= wake < h:
            out[wake] = [8] * w
    else:
        left = c1 < pos
        width = c1 - c0 + 1
        nc0 = pos - width if left else pos + 1
        dc = nc0 - c0
        for r, c in points:
            out[r][c + dc] = grid[r][c]
        wake = nc0 - 1 if left else nc0 + width
        if 0 <= wake < w:
            for r in range(h):
                out[r][wake] = 8
    return out
